const fs = require('fs');
const path = require('path');

const userDataDir = '/home/node/user_data';
const registryPath = path.join(userDataDir, 'trackers_registry.json');
const memoryPath = path.join(userDataDir, 'memory_rules.json');

if (!fs.existsSync(userDataDir)) {
  fs.mkdirSync(userDataDir, { recursive: true });
}

if (!fs.existsSync(registryPath)) {
  fs.writeFileSync(registryPath, JSON.stringify({ trackers: {} }, null, 2), 'utf8');
}

if (!fs.existsSync(memoryPath)) {
  fs.writeFileSync(memoryPath, JSON.stringify({ morning_rules: [], custom_scopes: {} }, null, 2), 'utf8');
}

const trackersRegistry = JSON.parse(fs.readFileSync(registryPath, 'utf8'));
const memoryRules = JSON.parse(fs.readFileSync(memoryPath, 'utf8'));

const now = new Date();
const todayIsoDate = now.toISOString().slice(0, 10);
const nowMs = now.getTime();
const dayMs = 24 * 60 * 60 * 1000;

// 1. Purge expired volatile rules in memory_rules.json (expires_at < today)
let memoryChanged = false;
if (memoryRules.custom_scopes && typeof memoryRules.custom_scopes === 'object') {
  for (const [scopeName, rules] of Object.entries(memoryRules.custom_scopes)) {
    if (Array.isArray(rules)) {
      const filtered = rules.filter((r) => !r.expires_at || r.expires_at >= todayIsoDate);
      if (filtered.length !== rules.length) {
        memoryRules.custom_scopes[scopeName] = filtered;
        memoryChanged = true;
      }
    }
  }
}
if (memoryChanged) {
  fs.writeFileSync(memoryPath, JSON.stringify(memoryRules, null, 2), 'utf8');
}

// 2. Gather active trackers where include_in_morning_briefing === true
const cycleTrackers = [];
const overdueCollectionFollowUps = [];
const recentActivities = [];

const trackers = trackersRegistry.trackers || {};
for (const [trackerId, tracker] of Object.entries(trackers)) {
  if (!tracker || tracker.include_in_morning_briefing !== true) continue;

  const dataFilePath = path.join(userDataDir, `data_${trackerId}.json`);
  const records = fs.existsSync(dataFilePath)
    ? JSON.parse(fs.readFileSync(dataFilePath, 'utf8'))
    : [];

  if (tracker.type === 'CYCLE_STATE_MACHINE') {
    const steps = Array.isArray(tracker.cycle_config?.steps) && tracker.cycle_config.steps.length > 0
      ? tracker.cycle_config.steps
      : ['Step 1'];
    const currentIndex = Number(tracker.cycle_config?.current_index || 0) % steps.length;
    cycleTrackers.push({
      tracker_id: trackerId,
      display_name: tracker.display_name || trackerId,
      current_step: steps[currentIndex],
      current_index: currentIndex,
      steps,
      last_updated: tracker.cycle_config?.last_updated || null
    });
  } else if (tracker.type === 'COLLECTION_TABLE') {
    const cutoff10Days = nowMs - 10 * dayMs;
    const pendingMatches = records.filter((r) => {
      const statusStr = String(r.status || r.statut || r.state || '').toLowerCase();
      const isPendingQuote = ['quote', 'devis', 'pending', 'attente', 'sent', 'envoyé'].some((kw) => statusStr.includes(kw));
      if (!isPendingQuote) return false;
      const refDate = Date.parse(r.updated_at || r.created_at || r.date || '');
      return !Number.isNaN(refDate) && refDate <= cutoff10Days;
    });
    if (pendingMatches.length > 0) {
      overdueCollectionFollowUps.push({
        tracker_id: trackerId,
        display_name: tracker.display_name || trackerId,
        overdue_count: pendingMatches.length,
        items: pendingMatches.slice(0, 5)
      });
    }
  } else if (tracker.type === 'ACTIVITY_LOG') {
    const cutoff7Days = nowMs - 7 * dayMs;
    const recent = records.filter((r) => {
      const refDate = Date.parse(r.created_at || r.updated_at || r.date || '');
      return !Number.isNaN(refDate) && refDate >= cutoff7Days;
    });
    recentActivities.push({
      tracker_id: trackerId,
      display_name: tracker.display_name || trackerId,
      recent_7d_count: recent.length,
      recent_entries: recent.slice(-10)
    });
  }
}

const inputPayload = $input.first()?.json?.body || $input.first()?.json || {};
const customFocus = inputPayload.custom_focus || '';
const overrideSuggestion = inputPayload.override_suggestion || '';

return [
  {
    json: {
      current_date: todayIsoDate,
      current_timestamp: now.toISOString(),
      cycle_trackers: cycleTrackers,
      overdue_follow_ups: overdueCollectionFollowUps,
      recent_activities_7d: recentActivities,
      morning_rules: memoryRules.morning_rules || [],
      custom_scopes: memoryRules.custom_scopes || {},
      custom_focus: customFocus,
      override_suggestion: overrideSuggestion
    }
  }
];

