const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const https = require('https');
const { URL } = require('url');

const userDataDir = '/home/node/user_data';
const memoryPath = path.join(userDataDir, 'memory_rules.json');

const briefingText = ($input.first().json.output || '').trim();
const nowIso = new Date().toISOString();
const today = nowIso.slice(0, 10);

// 1. Save today's briefing state in memory_rules.json under custom_scopes.today_briefing_state
const memory = fs.existsSync(memoryPath)
  ? JSON.parse(fs.readFileSync(memoryPath, 'utf8'))
  : { morning_rules: [], custom_scopes: {} };

if (!memory.custom_scopes || typeof memory.custom_scopes !== 'object') {
  memory.custom_scopes = {};
}

memory.custom_scopes.today_briefing_state = [
  {
    id: crypto.randomUUID(),
    instruction: `Briefing matinal proposé le ${today} : ${briefingText}`,
    volatile: true,
    expires_at: today,
    created_at: nowIso
  }
];

fs.writeFileSync(memoryPath, JSON.stringify(memory, null, 2), 'utf8');

// 2. Dispatch to Discord via DISCORD_BRIEFING_WEBHOOK_URL if configured
const webhookUrl = (process.env.DISCORD_BRIEFING_WEBHOOK_URL || '').trim();
let discordSent = false;
let discordWarning = null;

function postDiscordWebhook(targetUrl, payloadObj) {
  return new Promise((resolve, reject) => {
    const parsed = new URL(targetUrl);
    const bodyStr = JSON.stringify(payloadObj);
    const req = https.request(
      {
        hostname: parsed.hostname,
        port: parsed.port || 443,
        path: parsed.pathname + parsed.search,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(bodyStr)
        }
      },
      (res) => {
        let resBody = '';
        res.on('data', (chunk) => { resBody += chunk; });
        res.on('end', () => {
          if (res.statusCode >= 200 && res.statusCode < 300) {
            resolve(true);
          } else {
            reject(new Error(`Discord HTTP ${res.statusCode}: ${resBody}`));
          }
        });
      }
    );
    req.on('error', reject);
    req.write(bodyStr);
    req.end();
  });
}

if (webhookUrl && webhookUrl.startsWith('http') && !webhookUrl.includes('/xxx/yyy')) {
  try {
    await postDiscordWebhook(webhookUrl, {
      username: 'Jarvis Morning Briefing',
      content: briefingText
    });
    discordSent = true;
  } catch (err) {
    discordWarning = err.message;
  }
} else {
  discordWarning = 'DISCORD_BRIEFING_WEBHOOK_URL is empty or placeholder; skipped Discord HTTP dispatch.';
}

return [
  {
    json: {
      status: 'ok',
      discord_sent: discordSent,
      ...(discordWarning ? { warning: discordWarning } : {}),
      briefing: briefingText,
      timestamp: nowIso
    }
  }
];
